# region: gather
def gather(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: fold
def fold(xs):
    return [v for v in xs if v % 2 == 0]

# region: render
def render(xs, limit=12):
    return [v if v <= limit else limit for v in xs]

# region: digest
def digest(xs):
    return {'n': len(xs) - 1, 'total': sum(xs)}

# region: intake
def intake(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return intake(digest(render(fold(gather(raw)))))

